templatelistener.templatecode:
{if $__wcf->session->getPermission('user.archive.canAccess')}<script data-archive-url="{link controller='VzekcArchiveRedirect'}{/link}">{literal}
(() => {
	const url = new URL(document.currentScript.dataset.archiveUrl, location.href).href;
	document.addEventListener("click", (event) => {
		if (event.defaultPrevented || event.button !== 0 || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey) {
			return;
		}
		const link = event.target.closest("a[href]");
		if (link !== null && link.href === url) {
			event.preventDefault();
			window.open(url, "_blank", "noopener");
		}
	});
})();
{/literal}</script>{/if}
